// Select category and generate prompt
const categories = [
  'nasa-news',
  'space-facts',
  'satellite-tutorials',
  'astronomy-lessons'
];

const category = categories[Math.floor(Math.random() * categories.length)];

const prompts = {
  'nasa-news': 'Write a 500-word blog post about the latest NASA mission or discovery. Include orbital mechanics concepts, link to simulator, and make it SEO-friendly.',
  'space-facts': 'Write a 400-word blog post about an interesting space fact related to satellites or orbital mechanics. Include formulas and links to our simulator.',
  'satellite-tutorials': 'Write a 600-word tutorial explaining how a specific type of satellite works. Include orbital mechanics, formulas, and practical examples.',
  'astronomy-lessons': 'Write a 500-word educational post about astronomy concepts. Connect to orbital mechanics and include links to our learning resources.'
};

return {
  json: {
    category,
    prompt: prompts[category],
    temperature: 0.7,
    maxTokens: 1000
  }
};

// Parse AI response and format for blog API
const aiResponse = $input.item.json.choices[0].message.content;
const category = $('Generate Prompt').item.json.category;

// Extract title (first line or generate from content)
const lines = aiResponse.split('\n');
let title = lines[0].replace(/^#+\s*/, '').trim();
if (!title || title.length < 10) {
  title = 'Space Science and Orbital Mechanics Explained';
}

// Generate slug
const slug = title
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')\  .replace(/^-|-$/g, '');

// Extract excerpt (first paragraph or generate)
let excerpt = lines.find(line => line.trim().length > 50 && !line.startsWith('#'));
if (!excerpt) {
  excerpt = `Learn about ${title.toLowerCase()} and discover how orbital mechanics makes space exploration possible.`;
}
excerpt = excerpt.substring(0, 200);

// Get today's date
const today = new Date().toISOString().split('T')[0];

// Generate tags
const tagMap = {
  'nasa-news': ['NASA', 'space exploration', 'missions'],
  'space-facts': ['space facts', 'orbital mechanics', 'satellites'],
  'satellite-tutorials': ['satellites', 'tutorial', 'orbital mechanics'],
  'astronomy-lessons': ['astronomy', 'stars', 'space science']
};

const tags = tagMap[category] || ['space', 'orbital mechanics'];
const seoKeywords = tags.join(', ');

return {
  json: {
    slug,
    title,
    excerpt,
    content: aiResponse,
    category,
    date: today,
    tags,
    seoKeywords
  }
};
